DUR = {
    'ods_sync': 2, 'dwd_order': 3, 'dwd_user': 2, 'dwd_item': 2,
    'dws_trade': 4, 'dws_user': 2, 'ads_gmv': 1, 'ads_item': 1,
    'ads_kpi': 2, 'ads_retain': 2,
}
EDGES = [
    ('ods_sync', 'dwd_order'), ('ods_sync', 'dwd_user'), ('ods_sync', 'dwd_item'),
    ('dwd_order', 'dws_trade'), ('dwd_user', 'dws_trade'), ('dwd_user', 'dws_user'),
    ('dwd_item', 'ads_item'), ('dws_trade', 'ads_gmv'), ('dws_trade', 'ads_kpi'),
    ('dws_user', 'ads_kpi'), ('dws_user', 'ads_retain'),
]


def topo(nodes):
    indeg = {n: 0 for n in nodes}
    for u, v in EDGES:
        indeg[v] += 1
    ready = sorted(n for n in nodes if indeg[n] == 0)
    order = []
    while ready:
        cur = ready.pop(0)
        order.append(cur)
        for u, v in EDGES:
            if u == cur:
                indeg[v] -= 1
                if indeg[v] == 0:
                    ready.append(v)
        ready.sort()
    return order


nodes = sorted(DUR)
order = topo(nodes)
es = {n: 0 for n in nodes}
for cur in order:
    for u, v in EDGES:
        if u == cur:
            es[v] = max(es[v], es[cur] + DUR[cur])
ef = {n: es[n] + DUR[n] for n in nodes}
makespan = max(ef.values())

lf = {n: makespan for n in nodes}
for cur in reversed(order):
    succ = [v for u, v in EDGES if u == cur]
    if succ:
        lf[cur] = min(lf[v] - DUR[v] for v in succ)
ls = {n: lf[n] - DUR[n] for n in nodes}

critical = [n for n in order if ls[n] - es[n] == 0]
best = 0
for t in range(makespan):
    best = max(best, sum(1 for n in nodes if es[n] <= t < ef[n]))

print('关键路径用时 = ' + str(makespan))
print('关键链 = ' + ' -> '.join(critical))
print('总浮动 dwd_user = ' + str(ls['dwd_user'] - es['dwd_user']))
print('最大并行度 = ' + str(best))
